# Lists the frames of assets/homeros.ico and compares them, pixel by pixel,
# with a second .ico (one regenerated by assets/icons.py into a copy):
#   python3 -I ico.py assets/homeros.ico /tmp/regen/assets/homeros.ico
import io, struct, sys
from PIL import Image, ImageChops
def frames(p):
    d = open(p, 'rb').read(); n = struct.unpack('<H', d[4:6])[0]; out = {}
    for i in range(n):
        w, h, c, _, pl, bpp, sz, off = struct.unpack('<BBBBHHII', d[6+16*i:22+16*i])
        kind = 'PNG' if d[off:off+4] == b'\x89PNG' else 'BMP'
        print(p, w or 256, 'bpp', bpp, kind, sz)
        out[w or 256] = Image.open(io.BytesIO(d[off:off+sz])).convert('RGBA')
    return out
a, b = frames(sys.argv[1]), frames(sys.argv[2])
for n in a: print(n, 'identical' if ImageChops.difference(a[n], b[n]).getbbox() is None else 'DIFFERS')
